# owner: platform
import unittest
from tests.support import data_file
from hourglass.timesheet import timesheet_rows
from hourglass.schedule import load_schedule
from hourglass.models import Shift, Span
from hourglass.errors import ProjectError


def make_shift(worker, start, end):
    return Shift(worker, "mon", Span(start * 60, end * 60))


class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        shifts = [make_shift("Ana", 9, 10), make_shift("Bo", 9, 13), make_shift("Ana", 11, 12)]
        rows = timesheet_rows(shifts)
        self.assertEqual(rows, ["Bo: 1 shift, 4.0 hours", "Ana: 2 shifts, 2.0 hours"])

    def test_one_decimal_place(self):
        rows = timesheet_rows([Shift("Ana", "tue", Span(540, 620))])
        self.assertEqual(rows, ["Ana: 1 shift, 1.3 hours"])

    def test_ties_sorted_by_name(self):
        shifts = [make_shift("Zed", 9, 10), make_shift("Abe", 9, 10)]
        self.assertEqual(timesheet_rows(shifts)[0], "Abe: 1 shift, 1.0 hours")

    def test_empty_list(self):
        with self.assertRaises(ProjectError):
            timesheet_rows([])

    def test_blank_worker(self):
        for name in ("", "   "):
            with self.assertRaises(ProjectError):
                timesheet_rows([make_shift(name, 9, 10)])

    def test_sample_schedule(self):
        rows = timesheet_rows(load_schedule(data_file("schedule.csv")))
        self.assertEqual(len(rows), len({row.split(":")[0] for row in rows}))
